//! Differential tests for the Lean TOTP model in `verification/lean/totp-window`.
//! The golden corpus is generated by `lake exe corpus`. Rust tests run without Lean.

use fireemu_core_auth::mfa::{match_code, match_step_window, CodeMatch, TotpPolicy, TotpSecret};
use fireemu_core_auth::sha1::hmac_sha1;
use fireemu_core_auth::totp::{current_code, hotp, time_step, totp_at, TotpParams};
use fireemu_core_types::time::LogicalInstant;
use proptest::prelude::*;

const CORPUS: &str = include_str!("fixtures/lean-totp-window.corpus");
const RFC_INPUT: &[u8] = b"12345678901234567890";
const NANOS_PER_SECOND: i128 = 1_000_000_000;

fn key(tag: &str) -> &'static [u8] {
    match tag {
        "rfc" => RFC_INPUT,
        "empty" => &[],
        _ => panic!("unknown key tag {tag}"),
    }
}

fn last_step(token: &str) -> Option<u64> {
    (token != "-").then(|| token.parse().expect("last step"))
}

fn expected_result(token: &str) -> CodeMatch {
    match token {
        "no-match" => CodeMatch::NoMatch,
        "replayed" => CodeMatch::Replayed,
        _ => CodeMatch::Accepted {
            step: token
                .strip_prefix("accepted:")
                .expect("result tag")
                .parse()
                .expect("accepted step"),
        },
    }
}

#[test]
fn totp_matches_the_lean_specification_on_the_golden_corpus() {
    let mut lines = CORPUS.lines();
    assert!(lines.next().unwrap().starts_with("# Generated by "));
    let (declared, _) = lines
        .next()
        .unwrap()
        .strip_prefix("# ")
        .unwrap()
        .split_once(" cases. ")
        .unwrap();
    let declared: usize = declared.parse().expect("case count");
    let mut count = 0;
    for line in lines {
        count += 1;
        let fields: Vec<_> = line.split_ascii_whitespace().collect();
        match fields.as_slice() {
            ["step", period, nanos, step] => {
                let params = TotpParams {
                    period_seconds: period.parse().unwrap(),
                    digits: 6,
                };
                let at = LogicalInstant::from_nanos(nanos.parse().unwrap());
                assert_eq!(
                    time_step(&params, at),
                    step.parse::<u64>().unwrap(),
                    "{line}"
                );
            }
            ["validity", period, nanos, remaining] => {
                let params = TotpParams {
                    period_seconds: period.parse().unwrap(),
                    digits: 6,
                };
                let at = LogicalInstant::from_nanos(nanos.parse().unwrap());
                assert_eq!(
                    current_code(RFC_INPUT, &params, at).1,
                    remaining.parse::<u32>().unwrap(),
                    "{line}",
                );
            }
            ["mac", input, step, hex] => {
                let counter: u64 = step.parse().unwrap();
                assert_eq!(hex.len(), 40, "digest length at counter {counter}");
                let expected = std::array::from_fn(|i| {
                    u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).expect("digest byte")
                });
                assert!(
                    hmac_sha1(key(input), &counter.to_be_bytes()) == expected,
                    "digest mismatch for {input} at counter {counter}"
                );
            }
            ["hotp", input, period, nanos, digits, step, code, display] => {
                let key = key(input);
                let params = TotpParams {
                    period_seconds: period.parse().unwrap(),
                    digits: digits.parse().unwrap(),
                };
                let at = LogicalInstant::from_nanos(nanos.parse().unwrap());
                let counter = step.parse().unwrap();
                let code = code.parse().unwrap();
                assert_eq!(time_step(&params, at), counter, "{line}");
                assert_eq!(hotp(key, counter, params.digits), code, "{line}");
                assert_eq!(totp_at(key, &params, at), code, "{line}");
                assert_eq!(current_code(key, &params, at).0, *display, "{line}");
            }
            ["match", input, period, nanos, digits, window, last, code, result] => {
                let params = TotpParams {
                    period_seconds: period.parse().unwrap(),
                    digits: digits.parse().unwrap(),
                };
                let at = LogicalInstant::from_nanos(nanos.parse().unwrap());
                assert_eq!(
                    match_code(
                        &TotpSecret::new(key(input).to_vec()),
                        &params,
                        window.parse().unwrap(),
                        last_step(last),
                        code.parse().unwrap(),
                        at,
                    ),
                    expected_result(result),
                    "{line}"
                );
            }
            ["window", current, window, last, candidates, result] => {
                let candidates: Vec<u64> = if *candidates == "-" {
                    Vec::new()
                } else {
                    candidates.split(',').map(|s| s.parse().unwrap()).collect()
                };
                assert_eq!(
                    match_step_window(
                        current.parse().unwrap(),
                        window.parse().unwrap(),
                        last_step(last),
                        |step| candidates.contains(&step),
                    ),
                    expected_result(result),
                    "{line}"
                );
            }
            _ => panic!("invalid corpus case on line {}", count + 2),
        }
    }
    assert_eq!(declared, count, "case count in the header");
    assert!(count >= 200, "corpus too small: {count}");
}

#[test]
fn signed_floor_is_clamped_and_zero_period_returns_zero() {
    let policy = TotpPolicy::default();
    let params = policy.params();
    assert_eq!(
        (params.period_seconds, params.digits, policy.window_steps),
        (30, 6, 1)
    );
    let stride = 30 * NANOS_PER_SECOND;
    let after_max = (i128::from(u64::MAX) + 1) * stride;
    assert_eq!((-1i128).div_euclid(stride), -1);
    assert_eq!(time_step(&params, LogicalInstant::from_nanos(-1)), 0);
    assert_eq!(after_max.div_euclid(stride), i128::from(u64::MAX) + 1);
    assert_eq!(
        time_step(&params, LogicalInstant::from_nanos(after_max)),
        u64::MAX
    );
    let zero = TotpParams {
        period_seconds: 0,
        ..params
    };
    assert_eq!(time_step(&zero, LogicalInstant::MAX), 0);
}

#[test]
fn display_uses_one_character_for_zero_digits_and_nine_for_ten_digits() {
    let at = LogicalInstant::UNIX_EPOCH;
    let mut params = TotpParams {
        period_seconds: 30,
        digits: 0,
    };
    assert_eq!(current_code(RFC_INPUT, &params, at).0, "0");
    params.digits = 10;
    assert_eq!(current_code(RFC_INPUT, &params, at).0.len(), 9);
}

#[test]
fn a_stale_match_is_replayed_and_an_outside_code_can_collide() {
    let now = LogicalInstant::from_unix_seconds(30);
    let params = TotpParams {
        period_seconds: 30,
        digits: 0,
    };
    let factor = TotpSecret::new(RFC_INPUT.to_vec());
    let outside_code = hotp(RFC_INPUT, 2, params.digits);
    assert_eq!(outside_code, hotp(RFC_INPUT, 1, params.digits));
    assert_eq!(
        match_code(&factor, &params, 0, None, outside_code, now),
        CodeMatch::Accepted { step: 1 }
    );
    assert_eq!(
        match_code(&factor, &params, 0, Some(1), outside_code, now),
        CodeMatch::Replayed
    );
}

fn instants() -> impl Strategy<Value = i128> {
    prop_oneof![
        any::<i128>(),
        any::<i64>().prop_map(i128::from),
        Just(i128::MIN),
        Just(i128::MAX),
    ]
}

fn periods() -> impl Strategy<Value = u32> {
    prop_oneof![Just(0), Just(30), Just(60), any::<u32>()]
}

fn clock_reference(period: u32, nanos: i128) -> u64 {
    let stride = i128::from(period) * NANOS_PER_SECOND;
    let step = nanos.checked_div_euclid(stride).unwrap_or(0);
    u64::try_from(step.max(0)).unwrap_or(u64::MAX)
}

fn window_reference(current: u64, window: u8) -> impl Iterator<Item = u64> {
    let radius = i128::from(window);
    (-radius..=radius).filter_map(move |delta| u64::try_from(i128::from(current) + delta).ok())
}

fn outcome(matching: &[u64], last: Option<u64>) -> CodeMatch {
    if let Some(step) = matching
        .iter()
        .copied()
        .find(|step| last.is_none_or(|old| old < *step))
    {
        CodeMatch::Accepted { step }
    } else if matching.is_empty() {
        CodeMatch::NoMatch
    } else {
        CodeMatch::Replayed
    }
}

proptest! {
    /// `TW.time_step_clamped_floor`, `time_step_monotone` and `time_step_constant_in_period`.
    #[test]
    fn counters_follow_clamped_floor_and_stay_constant_within_a_period(
        period in periods(),
        a in instants(),
        b in instants(),
    ) {
        let params = TotpParams { period_seconds: period, digits: 6 };
        let read = |nanos| time_step(&params, LogicalInstant::from_nanos(nanos));
        let (earlier, later) = (a.min(b), a.max(b));
        let left = read(earlier);
        let right = read(later);
        prop_assert_eq!(left, clock_reference(period, earlier));
        prop_assert_eq!(right, clock_reference(period, later));
        prop_assert!(left <= right);

        if period != 0 {
            let stride = i128::from(period) * NANOS_PER_SECOND;
            let into_period = a.rem_euclid(stride);
            let at = read(a);
            if let Some(start) = a.checked_sub(into_period) {
                prop_assert_eq!(read(start), at);
            }
            if let Some(end) = a.checked_add(stride - 1 - into_period) {
                prop_assert_eq!(read(end), at);
            }
        }
    }

    /// `TW.truncate_lt`, `hotp_lt`, `show_code_padded` and `show_code_width`.
    #[test]
    fn truncation_bounds_the_code_and_decimal_format_preserves_it(
        key in prop::collection::vec(any::<u8>(), 0..80),
        period in periods(),
        nanos in instants(),
        digits in any::<u8>(),
    ) {
        let params = TotpParams { period_seconds: period, digits };
        let now = LogicalInstant::from_nanos(nanos);
        let step = clock_reference(period, nanos);
        let digest = hmac_sha1(&key, &step.to_be_bytes());
        let offset = usize::from(digest[19] & 15);
        let word = u32::from_be_bytes(digest[offset..offset + 4].try_into().unwrap());
        let truncated = word & 0x7fff_ffff;
        prop_assert!(truncated < 1 << 31);
        let expected = truncated % 10u32.pow(u32::from(digits.min(9)));
        let code = hotp(&key, step, digits);
        prop_assert_eq!(code, expected);
        prop_assert!(10u32.checked_pow(u32::from(digits)).is_none_or(|limit| code < limit));
        let display = current_code(&key, &params, now).0;
        prop_assert_eq!(display.len(), usize::from(digits.clamp(1, 9)));
        let raw = expected.to_string();
        let Some(padding) = display.strip_suffix(raw.as_str()) else {
            prop_assert!(false, "{display} does not end with {raw}");
            return Ok(());
        };
        prop_assert!(padding.bytes().all(|byte| byte == b'0'));
    }

    /// `TW.match_step_window_accepted_iff` and `window_no_overflow`.
    #[test]
    fn selector_visits_only_the_inclusive_window_and_returns_its_first_fresh_match(
        current in prop_oneof![any::<u64>(), 0..=300u64, (0..=300u64).prop_map(|n| u64::MAX - n)],
        window in any::<u8>(),
        last_delta in prop::option::of(-256i16..=256),
        mask in any::<u64>(),
    ) {
        let last = last_delta.map(|delta| current.saturating_add_signed(i64::from(delta)));
        let matches = |step: u64| mask & (1 << (step % 64)) != 0;
        let inside: Vec<_> = window_reference(current, window).collect();
        let matching: Vec<_> = inside.iter().copied().filter(|&step| matches(step)).collect();
        let expected = outcome(&matching, last);
        let mut visited = Vec::new();
        let actual = match_step_window(current, window, last, |step| {
            visited.push(step);
            matches(step)
        });
        let end = match expected {
            CodeMatch::Accepted { step } => inside.partition_point(|&candidate| candidate <= step),
            _ => inside.len(),
        };
        prop_assert_eq!(actual, expected);
        prop_assert!(inside.len() <= 511);
        prop_assert_eq!(visited.as_slice(), &inside[..end]);
    }

    /// `TW.match_code_accepts_iff`, `match_code_rejects_without_in_window_match` and
    /// `time_step_window_no_overflow`.
    #[test]
    fn code_is_accepted_exactly_at_the_first_fresh_in_window_match(
        period in periods(),
        nanos in instants(),
        digits in 0u8..=10,
        window in 0u8..=5,
        last_delta in prop::option::of(-6i16..=6),
        code_source_delta in -6i16..=6,
        detached in any::<bool>(),
    ) {
        let now = LogicalInstant::from_nanos(nanos);
        let params = TotpParams { period_seconds: period, digits };
        let current = clock_reference(period, nanos);
        let last = last_delta.map(|delta| current.saturating_add_signed(i64::from(delta)));
        let source = current.saturating_add_signed(i64::from(code_source_delta));
        let input = if detached { &[][..] } else { RFC_INPUT };
        let code = hotp(input, source, digits);
        let matching: Vec<_> = window_reference(current, window)
            .filter(|&step| !detached && hotp(input, step, digits) == code)
            .collect();
        prop_assert_eq!(
            match_code(&TotpSecret::new(input.to_vec()), &params, window, last, code, now),
            outcome(&matching, last)
        );
    }
}
